/* Local stub for Chart.js: lightweight shim to avoid runtime errors when offline.
   This is NOT the real Chart.js implementation. For full chart functionality,
   download Chart.js (e.g., chart.min.js) and replace this file.

   The shim exposes a minimal API: window.Chart with a Chart constructor that
   creates a canvas placeholder and logs a warning.
*/
(function (window) {
  function Chart(ctx, config) {
    console.warn(
      'Chart.js not found. This is a shim placeholder. Replace /vendor/chart.min.js with the official Chart.js to enable charts.'
    );
    // create a simple placeholder rendering
    try {
      var canvas =
        ctx && ctx.getContext
          ? ctx
          : typeof ctx === 'string'
            ? document.getElementById(ctx)
            : null;
      if (!canvas) return this;
      var ctx2d = canvas.getContext && canvas.getContext('2d');
      if (!ctx2d) return this;
      ctx2d.fillStyle = '#f3f4f6';
      ctx2d.fillRect(0, 0, canvas.width, canvas.height);
      ctx2d.fillStyle = '#9ca3af';
      ctx2d.font = '14px sans-serif';
      ctx2d.textAlign = 'center';
      ctx2d.fillText(
        'Chart.js (offline) - replace with real library',
        canvas.width / 2,
        canvas.height / 2
      );
    } catch (e) {
      /* ignore */
    }
    return this;
  }

  // minimal helpers to avoid code errors
  Chart.register = function () {};
  Chart.helpers = {};
  window.Chart = Chart;
})(window);
